EDITS = {'zoo_keeper/genome/species/check_desk.json': [('lines 95-95', '  "tris_lod0": 2000\n', '  "tris_lod0": 3000\n')], 'zoo_keeper/recipes/check_desk.py': [('lines 41-42', 'BURY = 0.008             # a part runs this far into the one it meets, never onto its face\n\n', 'BURY = 0.008             # a part runs this far into the one it meets, never onto its face\n#: A PEN ON A CHAIN each long side (1.141.0, the walker, 2026-10-27, with two photographs: "they had these pens\n#: attached with a little chain at banks"): a pen lying on the top, its cap end on a ball chain to a pad stuck to the\n#: top -- the counter pen set. Each part sits in the top, and no two of their faces lie within the census\'s 2.2 mm:\n#: the pen and the pad sink `PEN_SINK`, the chain half its section (a first build sank all three alike and the census\n#: found the chain\'s underside 1 mm off the pen\'s and the pad\'s).\nPEN_L, PEN_D = 0.14, 0.012       # the pen\'s length and its diameter, drawn square\nPAD = (0.05, 0.05, 0.012)        # the pad\'s footprint and height\n#: THE CHAIN IS A BALL CHAIN, LONG AND SLACK (the walker: "also longer chain"; the first photograph\'s runs about half\n#: a metre and curls). Beads `BEAD` square, `BEAD_STEP` apart along a cubic curve from the pad to the pen\'s cap that\n#: sags toward the desk\'s middle (`chain_reach`). Beads, not a bar:\n#: a bent bar\'s jointed segments share faces. The step keeps any two beads\' facing sides past the census\'s 2.2 mm\n#: (beside each other within a bead\'s width, they are at least sqrt(7.3**2 + 5**2) = 8.85 mm apart on centre).\nBEAD = 0.005\nBEAD_STEP = 0.0095\nCHAIN_GAP = (0.10, 0.20)         # between the pad\'s edge and the pen\'s cap end, the least and the most\nCHAIN_SAG = 0.15                 # the most the chain\'s handles pull toward the middle\nCHAIN_CLEAR = 0.006              # the first and last bead\'s centre off the pad and the pen\nPEN_IN = 0.08                    # the pad\'s centre this far inside the top\'s long edge\nPEN_OFF = 0.03                   # and this far past the date block\'s end\nPEN_SINK = 0.0055\n\n'), ('lines 46-47', 'PAPER = (0.95, 0.94, 0.90)\n\n', 'PAPER = (0.95, 0.94, 0.90)\nPEN = (0.10, 0.12, 0.30)         # a navy pen and pad, the second photograph\'s black as likely\nCHAIN_RGB = (0.70, 0.70, 0.72)   # a nickel ball chain\n\n\ndef chain_reach(w, d):\n    """``(gap, sag)``: how far the pen lies from its pad, and how far the chain\'s curve is pulled toward the desk\'s\n    middle -- each as much as the top allows. The pen\'s far end stays 3 cm inside the top\'s end; the chain\'s lowest\n    bead (a cubic sags 3/4 of its handles\' pull) stays a bead and the census\'s tolerance clear of the other side\'s\n    slip (`SLIP`, at 0.15 of the depth from the middle)."""\n    near = DATE_W / 2.0 + PEN_OFF + PAD[0] + PEN_L       # pad and pen, without the gap\n    gap = max(CHAIN_GAP[0], min(CHAIN_GAP[1], w / 2.0 - 0.03 - near))\n    slip_edge = 0.15 * d + SLIP[1] / 2.0\n    sag = min(CHAIN_SAG, (d / 2.0 - PEN_IN - slip_edge - BEAD - 0.003) / 0.75)\n    return gap, sag\n\n\ndef ball_chain(a, b, sag):\n    """The beads\' centres ``[(x, y)]`` along a cubic from ``a`` to ``b`` whose handles both pull ``sag`` in y: a slack\n    chain lying on the top. One every `BEAD_STEP` of arc, the ends included."""\n    import math\n    (ax, ay), (bx, by) = a, b\n    p1, p2 = (ax, ay + sag), (bx, by + sag)\n\n    def at(u):\n        v = 1.0 - u\n        return (v ** 3 * ax + 3 * v * v * u * p1[0] + 3 * v * u * u * p2[0] + u ** 3 * bx,\n                v ** 3 * ay + 3 * v * v * u * p1[1] + 3 * v * u * u * p2[1] + u ** 3 * by)\n    pts = [at(i / 400.0) for i in range(401)]\n    out, run = [pts[0]], 0.0\n    for q0, q1 in zip(pts, pts[1:]):\n        run += math.hypot(q1[0] - q0[0], q1[1] - q0[1])\n        if run >= BEAD_STEP:\n            out.append(q1)\n            run = 0.0\n    return out\n\n'), ('lines 101-102', '    parts.append(("CheckDesk_Paper", "paper", cards + slips, PAPER))\n    return parts\n', '    parts.append(("CheckDesk_Paper", "paper", cards + slips, PAPER))\n    # the pens: on each long side, beyond the date block\'s end on the side away from that side\'s slip\n    pens, pads, chains = [], [], []\n    for s in (-1.0, 1.0):\n        px = -s * (DATE_W / 2.0 + PEN_OFF + PAD[0] / 2.0)\n        py = s * (d / 2.0 - PEN_IN)\n        pads.append(((px, py, top_z1 + PAD[2] / 2.0 - PEN_SINK), PAD))\n        gap, sag = chain_reach(w, d)\n        e = px - s * (PAD[0] / 2.0 + gap)                    # the pen\'s cap end\n        chains += [((x, y, top_z1), (BEAD, BEAD, BEAD))\n                   for x, y in ball_chain((px - s * (PAD[0] / 2.0 + CHAIN_CLEAR), py),\n                                          (e + s * CHAIN_CLEAR, py), -s * sag)]\n        pens.append(((e - s * PEN_L / 2.0, py, top_z1 + PEN_D / 2.0 - PEN_SINK), (PEN_L, PEN_D, PEN_D)))\n    parts.append(("CheckDesk_Pen", "paper", pens, PEN))\n    parts.append(("CheckDesk_PenPad", "paper", pads, PEN))\n    parts.append(("CheckDesk_PenChain", "paper", chains, CHAIN_RGB))\n    return parts\n')], 'tests/test_check_desk.py': [('lines 69-69', '        assert (b[0] - sb[0] / 2.0) - (a[0] + sa[0] / 2.0) > 0.3, w\n', '        assert (b[0] - sb[0] / 2.0) - (a[0] + sa[0] / 2.0) > 0.3, w\n\n\n@pytest.mark.parametrize("dims", [(1.0, 0.6, 1.0), (1.6, 0.9, 1.1), (2.4, 1.0, 1.1), (3.2, 1.2, 1.2)])\ndef test_bpy_a_pen_on_a_ball_chain_each_side(tmp_path, dims):\n    """1.141.0, the walker: "they had these pens attached with a little chain at banks", then "also longer chain". Two\n    pens, each on its pad by a slack chain of separate beads that clears the slips, every part on the top and inside\n    it, the library\'s desks (1.6 and 2.4 m) with 0.3 m of chain or more. FAILS ON 1.140.0, which draws no pen."""\n    pytest.importorskip("bpy")\n    import math\n    from zoo_keeper.recipes import check_desk as K\n    w, d, h = dims\n    parts = {name: boxes for name, _k, boxes, _c in K.layout(w, d, h)}\n    pens, pads, beads = parts["CheckDesk_Pen"], parts["CheckDesk_PenPad"], parts["CheckDesk_PenChain"]\n    assert len(pens) == len(pads) == 2 and len(beads) % 2 == 0\n    for c, s in pens + pads + beads:\n        assert abs(c[0]) + s[0] / 2.0 <= w / 2.0 - 0.02 and abs(c[1]) + s[1] / 2.0 <= d / 2.0\n    slip_edge = 0.15 * d + K.SLIP[1] / 2.0\n    for c, s in beads:\n        assert abs(c[1]) - s[1] / 2.0 > slip_edge + 0.002, (dims, c)\n    half = beads[: len(beads) // 2]\n    run = sum(math.hypot(b[0][0] - a[0][0], b[0][1] - a[0][1]) for a, b in zip(half, half[1:]))\n    if w >= 1.6:\n        assert run >= 0.30, run\n    # no two beads\' sides face each other within the census\'s tolerance: sides face where the beads overlap across\n    # them (within a bead on the other axis), so a diagonal neighbour 6.9 mm off on both axes faces nothing\n    k = K.BEAD + 0.0022\n    for i, (a, sa) in enumerate(beads):\n        for b, sb in beads[i + 1:]:\n            dx, dy = abs(a[0] - b[0]), abs(a[1] - b[1])\n            assert not ((dx < k and dy < K.BEAD) or (dy < k and dx < K.BEAD)), (a, b)\n\n\ndef test_bpy_the_widest_desk_is_within_its_budget(tmp_path):\n    pytest.importorskip("bpy")\n    budget = genome.load_species("check_desk")["budgets"]["tris_lod0"]\n    meshes, _pts = _build(tmp_path, (3.2, 1.2, 1.2))\n    tris = sum(len(p.vertices) - 2 for o in meshes for p in o.data.polygons)\n    assert tris <= budget, (tris, budget)\n')]}
NEW_FILES = {}
CHANGELOG = '## [1.141.0] - the check desk\'s pens on their chains\n\nThe walker, 2026-10-27, with two photographs: "they had these pens attached with a little chain at banks", then "also\nlonger chain".\n\n### Added\n- **A pen on a ball chain each long side of `check_desk`**: the counter pen set -- a pen lying on the top, its cap end\n  on a chain to a pad stuck to the top, navy (the photographs\' navy and black). Beyond the date block\'s end, on the\n  side away from that side\'s slip.\n  - The chain is separate beads (`BEAD` 5 mm, `BEAD_STEP` 9.5 mm apart) along a slack cubic from the pad to the pen,\n    sagging toward the desk\'s middle: 0.33 m of chain on the library\'s 1.6 and 2.4 m desks, 0.19 m on the smallest.\n    `chain_reach` sets the pen\'s distance and the sag from the top\'s size, the chain clear of the slips. Beads, not a\n    bar: a bent bar\'s jointed segments share faces.\n  - In the desk\'s second material (the paper\'s white plastic) as `Wear` colour: still two materials.\n  - The coplanar census finds none at any corner. A first build sank the pen, the pad and the chain alike and the\n    census found the chain\'s underside 1 mm off the pen\'s and the pad\'s (2 pairs a corner); the pen and pad now sink\n    5.5 mm, the chain 2.5 mm.\n\n### Changed\n- **`check_desk`\'s budget is 3,000 triangles** (was 2,000): the default desk builds 1,972, the widest (3.2 m) 2,764,\n  the chains\' 68 beads 816 of it.\n\n### Tests\n- `tests/test_check_desk.py`: a pen on a ball chain each side, on the top, clear of the slips, 0.3 m of chain on the\n  library\'s desks, no two beads facing within the census\'s tolerance (fails on 1.140.0); the widest desk within its\n  budget.\n\n'
OLD_VERSION, NEW_VERSION = '1.140.0', '1.141.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
